import versionData from '../../version.json';

/**
 * Build metadata interface
 */
export interface BuildMetadata {
    version: string;
    commit: string;
    branch: string | null;
    buildDate: string;
    environment: 'production' | 'development';
}

/**
 * A generated file can arrive incomplete if the generator changes or someone
 * hand-edits it; this keeps the cast honest instead of trusting it.
 */
function isNonEmptyString(value: unknown): boolean {
    return typeof value === 'string' && value !== '';
}

function isParseableDate(value: unknown): boolean {
    return typeof value === 'string' && Number.isNaN(Date.parse(value)) === false;
}

function isBuildMetadata(value: unknown): value is BuildMetadata {
    if (typeof value !== 'object' || value === null) {
        return false;
    }

    const candidate = value as Record<string, unknown>;

    return (
        isNonEmptyString(candidate.version) &&
        isNonEmptyString(candidate.commit) &&
        (candidate.branch === null || typeof candidate.branch === 'string') &&
        isParseableDate(candidate.buildDate) &&
        (candidate.environment === 'production' || candidate.environment === 'development')
    );
}

/**
 * Get complete build metadata including version, commit, branch, etc.
 *
 * version.json is generated by scripts/generate-version.mjs during install,
 * dev start and build; see the hooks in package.json.
 *
 * @returns {BuildMetadata} Complete build information
 * @throws {Error} If version.json does not contain valid build metadata
 */
export function getVersionMetadata(): BuildMetadata {
    if (isBuildMetadata(versionData) === false) {
        throw new Error(
            'Invalid build metadata in version.json: expected a version, commit, '
            + 'branch, buildDate and environment. Regenerate it with '
            + 'node scripts/generate-version.mjs.'
        );
    }

    return versionData;
}

/**
 * Get formatted version string with commit SHA
 *
 * Format varies by environment and branch:
 * - Production: "VERSION (COMMIT)" e.g., "X.Y.Z (1ce5e97)"
 * - Development (feature branch): "VERSION (BRANCH@COMMIT)" e.g., "X.Y.Z (013-build-identification@a1b2c3d)"
 * - Development (main/master): "VERSION (COMMIT)" e.g., "X.Y.Z (1ce5e97)"
 *
 * @returns {string} Formatted version string
 */
export function getFormattedVersion(): string {
    const metadata = getVersionMetadata();
    const { version, commit, branch, environment } = metadata;

    // Show branch only for feature branches (not main/master) in development
    const showBranch =
        branch !== null &&
        branch !== 'main' &&
        branch !== 'master' &&
        environment === 'development';

    if (showBranch && branch !== null) {
        return `${version} (${branch}@${commit})`;
    } else {
        return `${version} (${commit})`;
    }
}

/**
 * Get the application version (backward compatible)
 *
 * @returns {string} Semantic version only (e.g., "X.Y.Z")
 */
export function getVersion(): string {
    return getVersionMetadata().version;
}
